"""Argument parsing and lazy dispatch for ``python -m linkvault``."""

import argparse
import os

from .core import parse_timestamp


def _nonempty(value):
    if not value:
        raise argparse.ArgumentTypeError("must not be empty")
    return value


def _port(value):
    try:
        port = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError("port must be an integer from 0 to 65535")
    if not 0 <= port <= 65535:
        raise argparse.ArgumentTypeError("port must be an integer from 0 to 65535")
    return port


def _rate_limit(value):
    try:
        limit = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError("rate limit must be an integer >= 1")
    if limit < 1:
        raise argparse.ArgumentTypeError("rate limit must be an integer >= 1")
    return limit


def _timestamp(value):
    try:
        parse_timestamp(value)
    except ValueError:
        raise argparse.ArgumentTypeError("expected a valid YYYY-MM-DDTHH:MM:SSZ timestamp")
    return value


def make_parser():
    parser = argparse.ArgumentParser(prog="linkvault")
    commands = parser.add_subparsers(dest="command", required=True)

    serve = commands.add_parser("serve")
    serve.add_argument("--db", required=True)
    serve.add_argument("--admin-key", required=True, type=_nonempty)
    serve.add_argument("--port", type=_port, default=8000)
    serve.add_argument("--rate-limit", type=_rate_limit, default=60)
    serve.add_argument("--fake-clock", type=_timestamp)

    token = commands.add_parser("token")
    token_commands = token.add_subparsers(dest="token_command", required=True)
    create = token_commands.add_parser("create")
    create.add_argument("--admin-key", required=True, type=_nonempty)

    shorten = commands.add_parser("shorten")
    shorten.add_argument("url")
    shorten.add_argument("--slug")
    shorten.add_argument("--expires-in", type=int)
    listing = commands.add_parser("list")
    stats = commands.add_parser("stats")
    stats.add_argument("slug")
    delete = commands.add_parser("delete")
    delete.add_argument("slug")

    for leaf in (create, shorten, listing, stats, delete):
        leaf.add_argument("--server", default=os.environ.get("LINKVAULT_SERVER"))
        leaf.add_argument("--token", default=os.environ.get("LINKVAULT_TOKEN"))
    return parser


def main(argv=None) -> int:
    parser = make_parser()
    args = parser.parse_args(argv)
    if args.command == "serve":
        from .server import serve

        return serve(args)

    if not args.server:
        parser.error("--server or LINKVAULT_SERVER is required")
    if args.command != "token" and not args.token:
        parser.error("--token or LINKVAULT_TOKEN is required")

    from .client import run

    return run(args)


if __name__ == "__main__":
    raise SystemExit(main())

"""Small urllib wrapper for the five Linkvault client commands."""

import json
import sys
from urllib.error import HTTPError, URLError
from urllib.parse import quote
from urllib.request import HTTPRedirectHandler, Request, build_opener


class _NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def _write_json(body, stream):
    value = json.loads(body.decode("utf-8"))
    print(json.dumps(value, separators=(",", ":"), ensure_ascii=True), file=stream)


def run(args) -> int:
    headers = {}
    body = None
    if args.command == "token":
        method, path = "POST", "/v1/tokens"
        headers["X-Admin-Key"] = args.admin_key
    else:
        headers["Authorization"] = "Bearer " + args.token
        if args.command == "shorten":
            method, path = "POST", "/v1/links"
            value = {"url": args.url}
            if args.slug is not None:
                value["slug"] = args.slug
            if args.expires_in is not None:
                value["expires_in"] = args.expires_in
            body = json.dumps(value, separators=(",", ":"), ensure_ascii=True).encode("utf-8")
            headers["Content-Type"] = "application/json"
        elif args.command == "list":
            method, path = "GET", "/v1/links"
        else:
            method = "DELETE" if args.command == "delete" else "GET"
            path = "/v1/links/" + quote(args.slug, safe="")

    try:
        request = Request(args.server.rstrip("/") + path, data=body, headers=headers, method=method)
        with build_opener(_NoRedirect()).open(request, timeout=10) as response:
            if args.command != "delete":
                _write_json(response.read(), sys.stdout)
        return 0
    except HTTPError as error:
        with error:
            body = error.read()
        try:
            _write_json(body, sys.stderr)
        except (ValueError, UnicodeError):
            # Redirects and non-Linkvault servers may have no JSON error body.
            _write_json(json.dumps({"error": {"code": "http_error", "message": str(error)}}).encode("utf-8"), sys.stderr)
        return 1
    except (URLError, OSError) as error:
        print("Connection failure: " + str(error), file=sys.stderr)
        return 3
